g1"]=[[换人]],["arg2"]=[[sy11npc02a]],["arg3"]=[[sy11npc02b]],["id"]=[[rlt_sy11change07]]},["rlt_sy11gushi02"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL陈平安：这真是出自少侠之手？短短几日在下深感敬佩！;CYN你将陈平安走后发生的一些事讲述给了他。;YEL陈平安：真想不到，老先生竟对你寄予如此高的厚望。这些是我购买脸谱的银两，我在里面多放了一些，就当是我感谢老先生和少侠这些时日的忙碌。;CYN陈平安递给你一个装的鼓鼓囊囊的钱袋，并对你这鞠身一礼。;YEL陈平安：在下还有些事要办，就不送少侠回去了，还望少侠谅解。]],["arg3"]=[[2;2;2;2;2]],["id"]=[[rlt_sy11gushi02]]},["rlt_sy11renwubj04"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人陈平安拿到脸谱]],["arg3"]=1,["id"]=[[rlt_sy11renwubj04]]},["rlt_sy13addnpc01a"]={["arg1"]=[[添加人物]],["arg2"]=[[sy13npc02]],["id"]=[[rlt_sy13addnpc01a]]},["rlt_sy13addnpc02a"]={["arg1"]=[[添加人物]],["arg2"]=[[sy13npc02b]],["id"]=[[rlt_sy13addnpc02a]]},["rlt_sy13change01a"]={["arg1"]=[[换人]],["arg2"]=[[sy13npc02]],["arg3"]=[[sy13npc02a]],["id"]=[[rlt_sy13change01a]]},["rlt_sy13change02a"]={["arg1"]=[[换人]],["arg2"]=[[sy13npc02a]],["arg3"]=[[sy13npc02b]],["id"]=[[rlt_sy13change02a]]},["rlt_sy13gushi01a"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL陈平安：这真是出自少侠之手？短短几日在下深感敬佩！;CYN你将陈平安离开后发生的事情一一讲述给他。;YEL陈平安：真想不到，老先生竟对你寄予如此高的厚望。这些是我购买脸谱的银两，我在里面多放了一些，就当是我感谢老先生和少侠这些时日的忙碌。;CYN陈平安递给你一个装的鼓鼓囊囊的钱袋，并对你这鞠身一礼。;YEL陈平安：在下还有些事要办，就不送少侠回去了，还望少侠谅解。]],["arg3"]=[[2;2;2;2;2]],["id"]=[[rlt_sy13gushi01a]]},["rlt_sy13renwubj04"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人陈平安答谢]],["arg3"]=1,["id"]=[[rlt_sy13renwubj04]]},["rlt_sy1addnpc03"]={["arg1"]=[[添加人物]],["arg2"]=[[sy1npc_02e]],["id"]=[[rlt_sy1addnpc03]]},["rlt_sy1addnpc04"]={["arg1"]=[[添加人物]],["arg2"]=[[sy1npc_02g]],["id"]=[[rlt_sy1addnpc04]]},["rlt_sy1change06"]={["arg1"]=[[换人]],["arg2"]=[[fb05r19_1]],["arg3"]=[[fb05sy19_1]],["id"]=[[rlt_sy1change06]]},["rlt_sy1change07"]={["arg1"]=[[换人]],["arg2"]=[[fb05sy19_1]],["arg3"]=[[fb05sy19_1a]],["id"]=[[rlt_sy1change07]]},["rlt_sy1change08"]={["arg1"]=[[换人]],["arg2"]=[[sy1npc_02e]],["arg3"]=[[sy1npc_02f]],["id"]=[[rlt_sy1change08]]},["rlt_sy1change09"]={["arg1"]=[[换人]],["arg2"]=[[sy1npc_02f]],["arg3"]=[[sy1npc_02g]],["id"]=[[rlt_sy1change09]]},["rlt_sy1gushi01"]={["arg1"]=[[副本故事]],["arg2"]=[[CYN你与陈平安一路到此，并没发现异常。来到此处见一群孩童正在嬉闹，其中一个比较大的孩子见你二人到此便笑嘻嘻的跑过来向陈平安打招呼。;CYN从顾小虎与陈平安的交谈中你得知，昨日陈平安回来时这群孩童也在此嬉闹。而陈平安似乎还参与其中。]],["arg3"]=[[2;2]],["id"]=[[rlt_sy1gushi01]]},["rlt_sy1jtbj02"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人交谈顾小虎]],["arg3"]=1,["id"]=[[rlt_sy1jtbj02]]},["rlt_sy1text05"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL顾小虎：昨日大哥哥回来时还陪我们玩了一阵呢，后来二妮把脚扭伤了，就坐在大哥哥带来的包袱上休息。;YEL顾小虎：结果和我们一起玩的小兰，放纸鸢的时候一不小心被绊倒，一屁股摔在了二妞身上。;YEL顾小虎：嘿嘿嘿，不过二妞一直说大哥哥的包袱里放了好多石头呢！小兰摔在她身上的时候二妞的屁股被狠狠的硌了一下，到现在她爹娘都不让下床呢！]],["arg3"]=[[2;2;2]],["id"]=[[rlt_sy1text05]]},["rlt_sy1text06"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL陈平安：哎呀！听少侠这般分析下来，难不成这脸谱就是那个时候孩子说的石头？;YEL陈平安：那我今日之举岂不是错怪老人家了。;YEL陈平安：少侠！今日之事是在下鲁莽了，明日还请劳烦少侠前来此处，与我一同前往天都峰，到时，还请少侠帮我向老人家说明情况。;YEL陈平安：虽说这件事错在于我，但那位老人家脾气古怪，在下实在是应付不来。]],["arg3"]=[[2;2;2;2]],["id"]=[[rlt_sy1text06]]},["rlt_sy2addnpc01"]={["arg1"]=[[添加人物]],["arg2"]=[[sy2npc_02]],["id"]=[[rlt_sy2addnpc01]]},["rlt_sy2addnpc02"]={["arg1"]=[[添加人物]],["arg2"]=[[sy2npc_02a]],["id"]=[[rlt_sy2addnpc02]]},["rlt_sy2change01"]={["arg1"]=[[换人]],["arg2"]=[[sy2npc_02]],["arg3"]=[[sy2npc_02a]],["id"]=[[rlt_sy2change01]]},["rlt_sy2renwubj01"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人陈平安出发]],["arg3"]=1,["id"]=[[rlt_sy2renwubj01]]},["rlt_sy2text01"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL陈平安：少侠你来了啊！]],["id"]=[[rlt_sy2text01]]},["rlt_sy2text02"]={["arg1"]=[[副本故事]],["arg2"]=[[YEL陈平安：昨日之事我已经深刻反思，这便备了厚礼登门道歉，希望老人家可以谅解。;YEL陈平安：此程还需劳烦少侠，等到天都峰见到老者，还望少侠能替在下解释一番。]],["arg3"]=[[2;2]],["id"]=[[rlt_sy2text02]]},["rlt_syrenwujieshubj"]={["arg1"]=[[玩家时间标记设置]],["arg2"]=[[21手艺人任务结束时间]],["arg3"]=1,["id"]=[[rlt_syrenwujieshubj]]},["rlt_syrenwujindubj"]={["arg1"]=[[玩家标记设置]],["arg2"]=[[21手艺人任务进度]],["arg3"]=1,["id"]=[[rlt_syrenwujindubj]]},["rlt_text1"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN老大娘：那个天杀的，偷了我的老母鸡啊，这可怎么办呐。]],["id"]=[[rlt_text1]],["jobstart"]=[[fb05rw01]]},["rlt_text10"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL谢二虎：这.这是娘的发簪，我..我还是回去一趟吧。]],["id"]=[[rlt_text10]]},["rlt_text11"]={["arg1"]=[[文本输出]],["arg2"]=[[你重重的拍了一下石像的身体，顿时觉得手痛的生疼，然而石像并没有什么变化。]],["id"]=[[rlt_text11]]},["rlt_text12"]={["arg1"]=[[文本输出]],["arg2"]=[[你重重地拍向石像，石像被你拍碎了，石像后方传来轰隆声，一扇小门出现在你的眼中，里面似乎是一间密室，你走了进去。]],["id"]=[[rlt_text12]]},["rlt_text13"]={["arg1"]=[[文本输出]],["arg2"]=[[CYN杂货铺老板：唉，都是爹不好，当年一心赚钱想让你和你娘过得更好些，直到你娘过世之后我才发现最重要的是你们呐。
谢二虎：别说了，爹，以后我一定好好干活，再也不游手好闲了。]],["id"]=[[rlt_text13]],["jobend"]=[[fb05rw04]]},["rlt_text14"]={["arg1"]=[[文本输出]],["arg2"]=[[你抚摸着玉像，看着玉像美丽的面庞，不由得呆了。]],["id"]=[[rlt_text14]]},["rlt_text15"]={["arg1"]=[[文本输出]],["arg2"]=[[突然，你发现蒲团面上的一层薄薄的蒲草已经破裂，露出下面一物！]],["id"]=[[rlt_text15]],["jobend"]=[[fb05rw06]],["jobstart"]=[[fb06rw01]]},["rlt_text16"]={["arg1"]=[[文本输出]],["arg2"]=[[你在蒲团上冲着玉像磕了一个头。]],["id"]=[[rlt_text16]]},["rlt_text17"]={["arg1"]=[[文本输出]],["arg2"]=[[你跳入湖中，向湖的对面游去，游了许久到了对岸。]],["id"]=[[rlt_text17]],["jobstart"]=[[fb05rw06]]},["rlt_text18"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL黑衣人：算你厉害。
WHT黑衣人逃走了。]],["id"]=[[rlt_text18]]},["rlt_text19"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL王铁手：这位朋友武功高强，我自愧不如，既然败在你手下，要杀要剐悉听尊便，我绝无二话！]],["id"]=[[rlt_text19]],["jobend"]=[[fb05rw01]]},["rlt_text2"]={["arg1"]=[[文本输出]],["arg2"]=[[流氓：这老母鸡下酒真不错呀。
地痞：那是当然了，来，咱们再喝！]],["id"]=[[rlt_text2]]},["rlt_text20"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL翠花：我知道了，你把这个交给刘能吧。]],["id"]=[[rlt_text20]]},["rlt_text21"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL刘能：太好了，多谢你了，对了，可别到处说这件事哦。]],["id"]=[[rlt_text21]],["jobend"]=[[fb05rw02]]},["rlt_text22"]={["arg1"]=[[文本输出]],["arg2"]=[[你将火升起来，架起了锅，将狗肉放了进去，放上盐，香料，煮了一锅狗肉，吃了起来。]],["id"]=[[rlt_text22]]},["rlt_text23"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL王小二：别伤我大哥！你有什么事情冲着我来吧，]],["id"]=[[rlt_text23]]},["rlt_text24"]={["arg1"]=[[文本输出]],["arg2"]=[[你运力双臂，双手扶着一块岩石，大喝一声：“动！”岩石晃动了一下，但是一晃即回。]],["id"]=[[rlt_text24]]},["rlt_text25"]={["arg1"]=[[文本输出]],["arg2"]=[[你运力双臂，双手扶着一块岩石，大喝一声：“动！”岩石缓缓转动，只转到一半，便见岩石后露出一个三尺来高的洞穴。]],["id"]=[[rlt_text25]]},["rlt_text26"]={["arg1"]=[[文本输出]],["arg2"]=[[你使劲浑身力气推动大门，大门缓缓地被推开了。]],["id"]=[[rlt_text26]]},["rlt_text27"]={["arg1"]=[[文本输出]],["arg2"]=[[你躺在石床上美美地睡了一觉。]],["id"]=[[rlt_text27]]},["rlt_text28"]={["arg1"]=[[文本输出]],["arg2"]=[[你翻动着书架，发现上面有个小条：“乘天地之正，御六气之辩，以游于无穷，是为逍遥。”看着看着，忽然猛的一掌向书架打去！震得书架“克拉，克拉”的响了几声。]],["id"]=[[rlt_text28]]},["rlt_text29"]={["arg1"]=[[文本输出]],["arg2"]=[[黑衣人：嗯？什么人？]],["id"]=[[rlt_text29]]},["rlt_text3"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL流氓：你…你等着。]],["id"]=[[rlt_text3]]},["rlt_text30"]={["arg1"]=[[文本输出]],["arg2"]=[[你翻动着书架，发现上面有个小条：“乘天地之正，御六气之辩，以游于无穷，是为逍遥。”看着看着，忽然猛的一掌向书架打去！突然啪地一声，有一件东西从书架上掉了下来！]],["id"]=[[rlt_text30]]},["rlt_text31"]={["arg1"]=[[文本输出]],["arg2"]=[[你翻阅着掌法总谱，上面一些精妙的见解，让你受益匪浅。]],["id"]=[[rlt_text31]],["jobend"]=[[fb05rw05lg]]},["rlt_text32"]={["arg1"]=[[文本输出]],["arg2"]=[[你翻阅着掌法总谱，上面的知识你已经融会贯通，对你起不到什么帮助了。]],["id"]=[[rlt_text32]],["jobend"]=[[fb05rw05lg]]},["rlt_text33"]={["arg1"]=[[文本输出]],["arg2"]=[[你冲着麻雀跑过去，麻雀十分机灵地跳开了，你运起轻功追了上去，麻雀被你惊得老远，看来短时间是不会再来了。]],["id"]=[[rlt_text33]],["jobstart"]=[[fb05rw03]]},["rlt_text34"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL李四：小子，你敢对我动手！我叫你知道我的厉害！]],["id"]=[[rlt_text34]]},["rlt_text35"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL壮汉：我技不如人，你进去吧。]],["id"]=[[rlt_text35]]},["rlt_text36"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL王小二：好小子，居然敢动我的人，胆子不小！今天让你知道我的厉害！]],["id"]=[[rlt_text36]]},["rlt_text37"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL李麻子：唷，我的信啊，多谢了。
